CREATE TABLE v69909 (v69910 DOUBLE, v69911 DOUBLE) AS SELECT CONVERT_TZ(CAST('2001-01-01 00:00:00.123456' AS DATETIME), '+00:00', '+01:00') AS x3, CONVERT_TZ(CAST('2001-01-01 00:00:00.1234' AS DATETIME), '+04:00', '2003-10-26 04:00:00') AS x4, FIND_IN_SET(NOT 1 IN (0), x10) AS x5, 1 * -9223372036854775808 AS x6, RANK() OVER () + SUM(x13) OVER () AS x7, CONVERT_TZ(CAST('2001-01-01 00:00:00.1234' AS DATETIME), '+04:00', '2003-10-26 04:00:00') AS x8, MAX(x12.x11) AS x9